  sequence
    [ verifyTransition "transition1EmptyStart" GeneratedOwned JourneyEmpty 0,
      verifyTransition "transition2ActiveDecide" GeneratedOwned JourneyActive 0,
      verifyTransition "transition3ActiveDecide" GeneratedOwned JourneyActive 1,
      verifyTransition "transition4ActivePing" GeneratedOwned JourneyActive 2,
      verifyTransition "transition5ActiveRetire" GeneratedOwned JourneyActive 3,
      verifyTransition "transition6ActiveRetire" GeneratedOwned JourneyActive 4
    ]
  where
    verifyTransition label owner source edgeIndex =
